<?php
declare(strict_types=1);
namespace TNL\Mail;
require_once __DIR__.'/Router.php';require_once __DIR__.'/ExternalMail.php';require_once __DIR__.'/Reception.php';
final class Dispatch {
 public static function recipients(string $input): array {
  if(strlen($input)>13000||preg_match('/[\r\n\x00]/',$input))throw new \InvalidArgumentException('Lista de destinatarios inválida.');
  $out=[];foreach(preg_split('/[;,]+/',$input) as $value){$value=trim($value);if($value==='')continue;$address=ReplyComposer::address($value);$value=strtolower($address!==''?$address:$value);if(strlen($value)>254)throw new \InvalidArgumentException('Destinatario demasiado largo.');$out[$value]=$value;}if(count($out)>50)throw new \InvalidArgumentException('Máximo 50 destinatarios.');return array_values($out);
 }
 public static function send(\PDO $db,string $actor,int $user,string $request,string $to,string $cc,string $subject,string $body,bool $canExternal,?array $account,?string $owner,string $storage,?int $reply=null,array $thread=[],string $kind='new',?\Closure $transport=null): array {
  if(!preg_match('/^[a-f0-9]{48}$/D',$request))throw new \InvalidArgumentException('Formulario de envío inválido.');
  $db->exec('CREATE TABLE IF NOT EXISTS mail_dispatches(id INTEGER PRIMARY KEY,actor TEXT NOT NULL,request_key TEXT NOT NULL,kind TEXT NOT NULL,recipients_to TEXT NOT NULL,recipients_cc TEXT NOT NULL,subject TEXT NOT NULL,state TEXT NOT NULL,result TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(actor,request_key))');
  $q=$db->prepare('SELECT result,state FROM mail_dispatches WHERE actor=? AND request_key=?');$q->execute([$actor,$request]);if($old=$q->fetch(\PDO::FETCH_ASSOC))return ['state'=>$old['state'],'results'=>json_decode($old['result'],true),'duplicate_prevented'=>true];
  $tos=self::recipients($to);$ccs=array_values(array_diff(self::recipients($cc),$tos));if(!$tos||count($tos)+count($ccs)>50)throw new \InvalidArgumentException('Indica entre 1 y 50 destinatarios.');if(trim($subject)===''||strlen($subject)>200||strlen($body)<1||strlen($body)>50000)throw new \InvalidArgumentException('Revisa el asunto y el mensaje.');
  Router::init($db);$plans=[];$seen=[];$smtpTo=[];$smtpCc=[];foreach(['to'=>$tos,'cc'=>$ccs] as $type=>$list)foreach($list as $recipient){$p=Router::plan($db,$recipient);$key=$p['route'].':'.$p['recipient'];if(isset($seen[$key]))continue;$seen[$key]=true;$p['input']=$recipient;$p['type']=$type;$plans[]=$p;if($p['route']==='smtp'){if(!$canExternal)throw new \InvalidArgumentException('Administración debe habilitar tu permiso de envío externo.');if(!$account)throw new \InvalidArgumentException('Selecciona una cuenta SMTP en De o configura un buzón en tu perfil.');if($type==='to')$smtpTo[]=$p['recipient'];else $smtpCc[]=$p['recipient'];}elseif($user<1)throw new \InvalidArgumentException('Selecciona una identidad de usuario para enviar al equipo.');}
  $previous=$reply!==null?InternalMail::read($db,$user,$reply):null;if($reply!==null&&!$previous)throw new \InvalidArgumentException('Mensaje de respuesta no disponible.');
  $db->prepare('INSERT INTO mail_dispatches(actor,request_key,kind,recipients_to,recipients_cc,subject,state,result,created_at) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$actor,$request,$kind,json_encode($tos),json_encode($ccs),$subject,'attempting','[]',gmdate('c')]);$dispatch=(int)$db->lastInsertId();$results=[];
  foreach($plans as $p)if($p['route']==='internal'){try{$target=Directory::resolve($db,$p['recipient']);$parent=$previous&&in_array((int)$target['id'],[(int)$previous['sender_id'],(int)$previous['recipient_id']],true)?$reply:null;Router::send($db,$actor,$user,$p['recipient'],$subject,$body,false,fn()=>throw new \LogicException('Ruta interna inválida'),$parent,'html',['to'=>$tos,'cc'=>$ccs,'kind'=>$kind]);$results[]=['recipient'=>$p['input'],'route'=>'internal','status'=>'delivered'];}catch(\Throwable $e){$results[]=['recipient'=>$p['input'],'route'=>'internal','status'=>'failed'];}}
  if($smtpTo||$smtpCc){$smtpStatus='unconfirmed';try{$routeInfo=$owner!==null?Reception::outbound($db,$owner,$user,array_merge($smtpTo,$smtpCc),$storage,$thread):[];if($routeInfo)$thread=array_merge($thread,$routeInfo);$primary=array_shift($smtpTo)??'';$id=$transport?$transport($primary,$smtpTo,$smtpCc):ExternalMail::send($account,$primary,$subject,$body,null,$thread,'html',$smtpTo,$smtpCc);$smtpStatus='accepted';if(!empty($routeInfo['token']))Reception::link($db,$owner,$id,$routeInfo['token']);if($owner!==null)try{(new ExternalAccount($db,$storage))->recordSent($owner,implode(', ',$tos),$subject,$body,$id,$thread,'html',implode(', ',$ccs));}catch(\Throwable $e){}}catch(\Throwable $e){}foreach($plans as $p)if($p['route']==='smtp'){$results[]=['recipient'=>$p['input'],'route'=>'smtp','status'=>$smtpStatus];$db->prepare('INSERT INTO mail_routes(actor,recipient,route,status,created_at) VALUES(?,?,?,?,?)')->execute([$actor,$p['recipient'],'smtp',$smtpStatus,gmdate('c')]);}}
  if(!$smtpTo&&!$smtpCc&&!array_filter($plans,fn($p)=>$p['route']==='smtp')&&$owner!==null&&array_filter($results,fn($r)=>$r['status']==='delivered'))try{(new ExternalAccount($db,$storage))->recordSent($owner,implode(', ',$tos),$subject,$body,'<dispatch-'.$request.'@local.invalid>',$thread,'html',implode(', ',$ccs));}catch(\Throwable $e){}
  $state=count(array_filter($results,fn($r)=>in_array($r['status'],['failed','unconfirmed'],true)))?'partial_or_unconfirmed':'completed';$db->prepare('UPDATE mail_dispatches SET state=?,result=? WHERE id=?')->execute([$state,json_encode($results),$dispatch]);return ['state'=>$state,'results'=>$results];
 }
 public static function summary(array $result): string {$labels=['delivered'=>'entregado internamente','accepted'=>'aceptado por SMTP','failed'=>'falló la entrega interna','unconfirmed'=>'envío SMTP no confirmado'];$items=[];foreach($result['results']??[] as $r)$items[]=$r['recipient'].': '.($labels[$r['status']]??$r['status']);return $items?implode(' · ',$items):'Este envío ya está en proceso o no quedó confirmado. No lo reenvíes automáticamente.';}
 public static function recent(\PDO $db,string $actor): array {if(!$db->query("SELECT name FROM sqlite_master WHERE type='table' AND name='mail_dispatches'")->fetchColumn())return [];$q=$db->prepare('SELECT kind,recipients_to,recipients_cc,subject,state,result,created_at FROM mail_dispatches WHERE actor=? ORDER BY id DESC LIMIT 30');$q->execute([$actor]);return $q->fetchAll(\PDO::FETCH_ASSOC);}
}
